result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_mytool.py", "content": """"Pytest suite for the hand-written parser in mytool.py.

All tests drive parse_args() directly (no subprocess).
"""

import pytest

from mytool import USAGE, parse_args


# --------------------------------------------------------------- basics

def test_no_args_gives_defaults():
    assert parse_args([]) == {
        "verbose": 0,
        "output": None,
        "positional": [],
    }


def test_positionals_only():
    assert parse_args(["a", "b", "c"])["positional"] == ["a", "b", "c"]


# ------------------------------------------------------------ verbosity

def test_single_v_counts_one():
    assert parse_args(["-v"])["verbose"] == 1


def test_repeated_v_counts():
    assert parse_args(["-v", "-v", "-v"])["verbose"] == 3


def test_clustered_v_counts():
    assert parse_args(["-vvv"])["verbose"] == 3


# -------------------------------------------------------------- -o/--output

def test_short_o_separate_value():
    assert parse_args(["-o", "out.txt"])["output"] == "out.txt"


def test_long_output_separate_value():
    assert parse_args(["--output", "out.txt"])["output"] == "out.txt"


def test_long_output_equals_form():
    assert parse_args(["--output=out.txt"])["output"] == "out.txt"


def test_attached_short_value():
    assert parse_args(["-oout.txt"])["output"] == "out.txt"


# ------------------------------------------------------------- clustering

def test_cluster_with_trailing_o_takes_next_arg():
    got = parse_args(["-vvo", "out.txt"])
    assert got["verbose"] == 2
    assert got["output"] == "out.txt"
    assert got["positional"] == []


def test_cluster_then_more_args():
    got = parse_args(["-vo", "out.txt", "in.txt"])
    assert got == {
        "verbose": 1,
        "output": "out.txt",
        "positional": ["in.txt"],
    }


# --------------------------------------------------------- -- terminator

def test_double_dash_makes_everything_positional():
    got = parse_args(["--", "-v", "-o", "--output=x"])
    assert got == {
        "verbose": 0,
        "output": None,
        "positional": ["-v", "-o", "--output=x"],
    }


def test_option_before_double_dash_is_parsed():
    got = parse_args(["-v", "--", "-5"])
    assert got["verbose"] == 1
    assert got["positional"] == ["-5"]


def test_bare_dash_is_positional():
    assert parse_args(["-"])["positional"] == ["-"]


# ------------------------------------------------------ negative numbers

def test_negative_number_is_positional_without_terminator():
    got = parse_args(["-5"])
    assert got["positional"] == ["-5"]
    assert got["verbose"] == 0


@pytest.mark.parametrize("num", ["-0", "-42", "-3.14", "-.5"])
def test_various_negative_numbers_are_positional(num):
    assert parse_args([num])["positional"] == [num]


def test_negative_number_after_real_option():
    got = parse_args(["-v", "-7", "-o", "f"])
    assert got == {"verbose": 1, "output": "f", "positional": ["-7"]}


# ------------------------------------------------------- interleaving

def test_options_interleaved_with_positionals():
    got = parse_args(["a", "-v", "b", "--output=o", "c"])
    assert got == {"verbose": 1, "output": "o", "positional": ["a", "b", "c"]}


# ------------------------------------------------------- error handling

UNKNOWN = [
    (["--bogus"], "unknown option --bogus"),
    (["-z"], "unknown option -z"),
    (["-vz"], "unknown option -z"),          # bad short inside a cluster
    (["--"], ),                               # sentinel replaced below
]


@pytest.mark.parametrize(
    "argv,errfrag",
    [
        (["--bogus"], "unknown option --bogus"),
        (["-z"], "unknown option -z"),
        (["-vz"], "unknown option -z"),
        (["--verbos"], "unknown option --verbos"),  # no abbreviation
    ],
)
def test_unknown_option_exits_2_with_usage(argv, errfrag, capsys):
    with pytest.raises(SystemExit) as exc:
        parse_args(argv)
    assert exc.value.code == 2
    err = capsys.readouterr().err
    assert errfrag in err
    assert "usage:" in err
    assert err.strip().splitlines()[-1].startswith("usage:")


@pytest.mark.parametrize(
    "argv",
    [["-o"], ["--output"]],
)
def test_missing_option_value_exits_2(argv, capsys):
    with pytest.raises(SystemExit) as exc:
        parse_args(argv)
    assert exc.value.code == 2
    assert "requires an argument" in capsys.readouterr().err


def test_usage_line_matches_expected_text(capsys):
    with pytest.raises(SystemExit):
        parse_args(["--nope"])
    assert USAGE in capsys.readouterr().err
